#!/usr/bin/env python3
"""Recompute ground truth for CSX-237_Q2."""

from __future__ import annotations

import json
import math
import re
from collections import Counter
from pathlib import Path


TASK_ID = "CSX-237_Q2"
EVENT_ID = "CSX-237"


def load_json(path: Path) -> dict:
    with path.open("r", encoding="utf-8-sig") as handle:
        return json.load(handle)


def parse_depth_km(severity_text: str) -> float:
    match = re.search(r"Depth:\s*([0-9.]+)\s*km", severity_text)
    if not match:
        raise RuntimeError(f"Could not parse depth from severity text: {severity_text!r}")
    return float(match.group(1))


def rounded(value: float, digits: int) -> float:
    return round(float(value), digits)


def build_rubric() -> dict:
    return {
        "total_points": 20,
        "criteria": [
            {
                "name": "JSON result shape",
                "points": 3,
                "description": "Returns compact JSON with a result block, four ledger rows, a ledger_score, and the final numeric label.",
            },
            {
                "name": "Structured extraction",
                "points": 4,
                "description": "Extracts the event magnitude, depth, alert level, hazard family, masked OSM amenity counts, and WorldPop total from structured local files, using derived counts/totals rather than georeferencing metadata.",
            },
            {
                "name": "Formula calculations",
                "points": 5,
                "description": "Computes seismic_depth_score, school_share, safety_care_ratio, population_per_non_school_amenity, and population_per_care_node within tolerance.",
            },
            {
                "name": "Threshold ledger",
                "points": 4,
                "description": "Applies all four threshold tests and reports four passing ledger rows.",
            },
            {
                "name": "Final label",
                "points": 2,
                "description": "Reports ledger_score = 4 and label compound_seismic_high_facility_imbalance.",
            },
            {
                "name": "Rounding and units",
                "points": 2,
                "description": "Uses ratios as unitless values, population loads as people per node, and clear rounding for the returned metrics.",
            },
        ],
    }


def main() -> None:
    task_dir = Path(__file__).resolve().parent
    repo_root = task_dir.parents[2]
    package_dir = repo_root / "event_packages" / "standard_event_packages" / "packages" / EVENT_ID

    source_files = [
        "metadata/event.json",
        "data/event_reports/event_reports_002_Locked_event_anchor_2010_Maule_Chile_earthquake_and_tsunami.json",
        "data/event_catalogs/event_catalogs_006_04_event_specific_disaster_catalog_GDACS_event_list_for_package_time_window.json.json",
        "data/exposure_impact/exposure_impact_004_OpenStreetMap_Overpass_bounded_AOI_slice.json",
        "data/exposure_impact/exposure_impact_003_WorldPop_GP_100m_population_sum.json",
    ]

    event_meta = load_json(package_dir / source_files[0])
    event_anchor = load_json(package_dir / source_files[1])
    gdacs = load_json(package_dir / source_files[2])
    osm = load_json(package_dir / source_files[3])
    worldpop = load_json(package_dir / source_files[4])

    chile_features = [
        feature
        for feature in gdacs.get("features", [])
        if feature.get("properties", {}).get("iso3") == "CHL"
    ]
    if len(chile_features) != 1:
        raise RuntimeError(f"Expected one Chile alert feature, found {len(chile_features)}")

    props = chile_features[0]["properties"]
    magnitude = float(props["severitydata"]["severity"])
    depth_km = parse_depth_km(props["severitydata"]["severitytext"])
    alert_level = str(props["alertlevel"])
    alert_numeric = {"Green": 1, "Orange": 2, "Red": 3}[alert_level]

    elements = osm.get("elements", [])
    amenity_counts = Counter(
        element.get("tags", {}).get("amenity")
        for element in elements
        if isinstance(element.get("tags"), dict) and element.get("tags", {}).get("amenity")
    )
    counts = {
        "amenities": len(elements),
        "school": amenity_counts["school"],
        "police": amenity_counts["police"],
        "fire_station": amenity_counts["fire_station"],
        "hospital": amenity_counts["hospital"],
        "shelter": amenity_counts["shelter"],
    }

    safety_nodes = counts["police"] + counts["fire_station"]
    care_nodes = counts["hospital"] + counts["shelter"]
    non_school_amenities = counts["amenities"] - counts["school"]
    population = float(worldpop["population_sum"]["population"])

    compound_flag = int(
        event_meta["hazard_family"] == "earthquake_tsunami_geophysical"
        and "tsunami" in event_anchor["event_name"].lower()
    )
    seismic_depth_score = magnitude * alert_numeric / math.sqrt(depth_km)
    school_share = counts["school"] / counts["amenities"]
    safety_care_ratio = safety_nodes / care_nodes
    population_per_non_school_amenity = population / non_school_amenities
    population_per_care_node = population / care_nodes

    metrics = {
        "seismic_depth_score": rounded(seismic_depth_score, 3),
        "school_share": rounded(school_share, 3),
        "safety_care_ratio": rounded(safety_care_ratio, 3),
        "population_per_non_school_amenity": rounded(population_per_non_school_amenity, 1),
        "population_per_care_node": rounded(population_per_care_node, 1),
    }

    ledger = [
        {
            "row": "seismic_depth",
            "values": {
                "magnitude": magnitude,
                "depth_km": depth_km,
                "alert_numeric": alert_numeric,
                "seismic_depth_score": metrics["seismic_depth_score"],
            },
            "threshold_result": "pass"
            if magnitude >= 8.5 and depth_km <= 70.0 and alert_numeric == 3 and seismic_depth_score >= 4.0
            else "fail",
        },
        {
            "row": "compound_link",
            "values": {
                "compound_flag": compound_flag,
                "hazard_family": event_meta["hazard_family"],
            },
            "threshold_result": "pass" if compound_flag == 1 else "fail",
        },
        {
            "row": "facility_imbalance",
            "values": {
                "school_share": metrics["school_share"],
                "safety_care_ratio": metrics["safety_care_ratio"],
                "safety_nodes": safety_nodes,
                "care_nodes": care_nodes,
            },
            "threshold_result": "pass" if school_share >= 0.90 and safety_care_ratio >= 5.0 else "fail",
        },
        {
            "row": "population_load",
            "values": {
                "population_sum": rounded(population, 1),
                "non_school_amenities": non_school_amenities,
                "population_per_non_school_amenity": metrics["population_per_non_school_amenity"],
                "population_per_care_node": metrics["population_per_care_node"],
            },
            "threshold_result": "pass"
            if population_per_non_school_amenity >= 100000.0 and population_per_care_node >= 900000.0
            else "fail",
        },
    ]
    ledger_score = sum(1 for row in ledger if row["threshold_result"] == "pass")
    final_label = (
        "compound_seismic_high_facility_imbalance"
        if ledger_score == len(ledger)
        else "partial_numeric_match"
    )
    states = {row["row"]: row["threshold_result"] for row in ledger}

    expected_counts = {
        "amenities": 1000,
        "school": 945,
        "police": 36,
        "fire_station": 13,
        "hospital": 3,
        "shelter": 3,
    }
    if not (
        event_meta["package_id"] == EVENT_ID
        and event_anchor["event_name"] == "2010 Maule Chile earthquake and tsunami"
        and alert_level == "Red"
        and magnitude == 8.8
        and depth_km == 35.0
        and counts == expected_counts
        and ledger_score == 4
    ):
        raise RuntimeError("Package evidence no longer matches the CSX-237_Q2 numeric ledger")

    computed = {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "numeric",
        "target_family": "formula_threshold_ledger",
        "evaluation_mode": "deterministic",
        "difficulty_level": "L3",
        "primary_gt": {
            "result": {
                "ledger_score": ledger_score,
                "final_numeric_label": final_label,
                "seismic_depth_score": metrics["seismic_depth_score"],
                "school_share": metrics["school_share"],
                "safety_care_ratio": metrics["safety_care_ratio"],
                "population_per_non_school_amenity": metrics["population_per_non_school_amenity"],
                "population_per_care_node": metrics["population_per_care_node"],
            },
            "ledger": ledger,
            "calculation_note": (
                "All four rows pass: the ledger combines 8.8 magnitude, 35.0 km depth, "
                "Red alert, a 0.945 school share, a 49:6 safety-care split, and "
                "5823675.1 people."
            ),
        },
        "event": {
            "package_id": EVENT_ID,
            "event_name": event_anchor["event_name"],
            "hazard_family": event_meta["hazard_family"],
            "event_date": event_anchor["temporal_window"]["start_date"],
            "location_text": event_anchor["spatial_window"]["location_text"],
        },
        "formulas": {
            "seismic_depth_score": "magnitude * alert_numeric / sqrt(depth_km)",
            "school_share": "school_count / amenity_element_count",
            "safety_care_ratio": "(police_count + fire_station_count) / (hospital_count + shelter_count)",
            "population_per_non_school_amenity": "population_sum / (amenity_element_count - school_count)",
            "population_per_care_node": "population_sum / (hospital_count + shelter_count)",
        },
        "thresholds": {
            "seismic_depth": "magnitude >= 8.5 and depth_km <= 70 and alert_numeric == 3 and seismic_depth_score >= 4",
            "compound_link": "compound_flag == 1",
            "facility_imbalance": "school_share >= 0.90 and safety_care_ratio >= 5",
            "population_load": "population_per_non_school_amenity >= 100000 and population_per_care_node >= 900000",
            "final_label": "compound_seismic_high_facility_imbalance if ledger_score == 4 else partial_numeric_match",
        },
        "key_values": {
            "magnitude": magnitude,
            "depth_km": depth_km,
            "alert_level": alert_level,
            "alert_numeric": alert_numeric,
            "compound_flag": compound_flag,
            "population_sum": rounded(population, 1),
            "safety_nodes": safety_nodes,
            "care_nodes": care_nodes,
            "non_school_amenities": non_school_amenities,
            "ledger": ledger,
            "counts": counts,
            "states": states,
            "tolerances": {
                "score": 0,
                "ratio": 0.005,
                "share": 0.001,
                "population": 1.0,
            },
            "data_scope": {
                "masked_exposure_products": "OSM and WorldPop are used for declared derived amenity counts and population totals only; coordinates, place names, bbox, or other georeferencing metadata inside those masked products are not used to judge event-location validity.",
            },
        },
        "provenance": {
            "computed_by": "compute_gt.py",
            "notes": "Final label is defined by the four-row ledger score. Masked exposure products are authoritative for derived counts/totals only.",
            "source_files": source_files,
        },
        "rubric": build_rubric(),
    }

    output = task_dir / "computed_gt.json"
    output.write_text(json.dumps(computed, indent=2, sort_keys=False) + "\n", encoding="utf-8")


if __name__ == "__main__":
    main()
